<body>
<div class="wrap">
  <h1>Memory Match</h1>
  <p class="hint">Flip two cards to find a pair. Match all 8 pairs to win.</p>
  <div class="stats">
    <div class="stat"><span class="label">Moves</span><span class="value" id="moves">0</span></div>
    <div class="stat"><span class="label">Pairs</span><span class="value" id="pairs">0/8</span></div>
    <div class="stat"><span class="label">Best</span><span class="value" id="best">–</span></div>
  </div>
  <div class="board" id="board" role="group" aria-label="Memory card board"></div>
  <div class="controls">
    <button class="action" id="new" type="button">New game</button>
  </div>
  <div class="win hidden" id="win" role="status"></div>
  <p class="sr" id="status" aria-live="polite"></p>
</div>
<script>
(function () {
  var SYMBOLS = ['★','♦','♣','♠','♥','♪','✿','☀'];
  var board = document.getElementById('board');
  var movesEl = document.getElementById('moves');
  var pairsEl = document.getElementById('pairs');
  var bestEl = document.getElementById('best');
  var winEl = document.getElementById('win');
  var statusEl = document.getElementById('status');
  var newBtn = document.getElementById('new');

  var cards = [];        // {sym, matched, el}
  var first = null;
  var lock = false;
  var moves = 0;
  var matchedCount = 0;
  var best = null;
  var has = window.alfy && window.alfy.storage;

  function shuffle(a) {
    for (var i = a.length - 1; i > 0; i--) {
      var j = Math.floor(Math.random() * (i + 1));
      var t = a[i]; a[i] = a[j]; a[j] = t;
    }
    return a;
  }

  function buildDeck() {
    var deck = [];
    for (var i = 0; i < SYMBOLS.length; i++) { deck.push(SYMBOLS[i], SYMBOLS[i]); }
    return shuffle(deck);
  }

  function render() {
    board.innerHTML = '';
    cards.forEach(function (c, idx) {
      var btn = document.createElement('button');
      btn.className = 'card';
      btn.type = 'button';
      btn.setAttribute('aria-label', 'Card ' + (idx + 1));
      btn.setAttribute('aria-pressed', 'false');
      btn.innerHTML =
        '<span class="card-inner">' +
          '<span class="face back" aria-hidden="true">?</span>' +
          '<span class="face front" aria-hidden="true">' + c.sym + '</span>' +
        '</span>';
      btn.addEventListener('click', function () { onCard(c, btn); });
      c.el = btn;
      board.appendChild(btn);
    });
  }

  function updateStats() {
    movesEl.textContent = String(moves);
    pairsEl.textContent = matchedCount + '/8';
    bestEl.textContent = best === null ? '–' : String(best);
  }

  function say(msg) { statusEl.textContent = msg; }

  function onCard(c, btn) {
    if (lock || c.matched || c === first) return;
    btn.classList.add('flipped');
    btn.setAttribute('aria-pressed', 'true');
    if (first === null) {
      first = c;
      return;
    }
    moves++;
    updateStats();
    if (first.sym === c.sym) {
      first.matched = true;
      c.matched = true;
      first.el.classList.add('matched');
      btn.classList.add('matched');
      matchedCount++;
      updateStats();
      first = null;
      say('Match found. ' + matchedCount + ' of 8 pairs.');
      if (matchedCount === 8) finish();
    } else {
      lock = true;
      var a = first, b = c;
      first = null;
      a.el.classList.add('shake');
      btn.classList.add('shake');
      setTimeout(function () {
        a.el.classList.remove('flipped', 'shake');
        btn.classList.remove('flipped', 'shake');
        a.el.setAttribute('aria-pressed', 'false');
        btn.setAttribute('aria-pressed', 'false');
        lock = false;
      }, 800);
    }
  }

  function finish() {
    if (best === null || moves < best) { best = moves; saveBest(); }
    winEl.textContent = 'You won in ' + moves + ' moves!';
    winEl.classList.remove('hidden');
    say('Game complete in ' + moves + ' moves.');
  }

  function newGame() {
    first = null; lock = false; moves = 0; matchedCount = 0;
    winEl.classList.add('hidden');
    var deck = buildDeck();
    cards = deck.map(function (s) { return { sym: s, matched: false, el: null }; });
    render();
    updateStats();
    say('New game started. Flip two cards to find a pair.');
  }

  function saveBest() {
    if (has) { window.alfy.storage.set('memory-best', best); }
  }

  newBtn.addEventListener('click', newGame);

  if (has) {
    window.alfy.storage.get('memory-best').then(function (v) {
      if (typeof v === 'number') best = v;
      updateStats();
    }).catch(function () {});
  }

  newGame();
})();
</script>
</body>
</html>
